package com.fooddelivery.auth; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController{final UserRepository repo;final PasswordEncoder enc;final JwtService jwt; AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} record Register(@Email @NotBlank String email,@Size(min=6)String password,@NotBlank String fullName,String address,String phoneNumber){} record Login(@Email @NotBlank String email,@NotBlank String password){} record Response(String token,String email,String fullName,String role){} @PostMapping("/register") Response register(@Valid @RequestBody Register r){if(repo.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");var u=new User();u.setEmail(r.email());u.setPassword(enc.encode(r.password()));u.setFullName(r.fullName());u.setAddress(r.address());u.setPhoneNumber(r.phoneNumber());repo.save(u);return response(u);} @PostMapping("/login") Response login(@Valid @RequestBody Login r){var u=repo.findByEmail(r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!enc.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return response(u);} private Response response(User u){return new Response(jwt.token(u),u.getEmail(),u.getFullName(),u.getRole().name());}}